    private static func _createChord(_ name: String, _ firstFret: Double, _ strings: List<Double>, _ barreFrets: List<Double>? = nil) -> Chord {
        let chord: Chord = Chord()
        chord.name = name
        chord.firstFret = firstFret
        chord.strings = strings
        if TypeHelper.isTruthy(barreFrets) {
            chord.barreFrets = barreFrets!
        }
        return chord
    }

    public static func checkChords(_ score: Score) throws {
        let track: Track = score.tracks[0]
        let staff: Staff = track.staves[0]
        try TestGlobals.expect(jsNonNull(staff.chords).size).toBe(8.0)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("C", 1.0, List<Double>(0.0, 1.0, 0.0, 2.0, 3.0, -1.0)), track.staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats.jsElement(0).chord)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("Cm", 1.0, List<Double>(-1.0, -1.0, 0.0, 1.0, 3.0, -1.0)), track.staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats.jsElement(1).chord)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("C", 1.0, List<Double>(3.0, 5.0, 5.0, 5.0, 3.0, -1.0), List<Double>(3.0)), track.staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats.jsElement(2).chord)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("Cm", 1.0, List<Double>(3.0, 4.0, 5.0, 5.0, 3.0, -1.0), List<Double>(3.0)), track.staves.jsElement(0).bars.jsElement(0).voices.jsElement(0).beats.jsElement(3).chord)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("D", 1.0, List<Double>(2.0, 3.0, 2.0, 0.0, -1.0, -1.0), List<Double>(2.0)), track.staves.jsElement(0).bars.jsElement(1).voices.jsElement(0).beats.jsElement(0).chord)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("Dm", 1.0, List<Double>(1.0, 3.0, 2.0, 0.0, -1.0, -1.0)), track.staves.jsElement(0).bars.jsElement(1).voices.jsElement(0).beats.jsElement(1).chord)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("D", 5.0, List<Double>(5.0, 7.0, 7.0, 7.0, 5.0, -1.0), List<Double>(5.0)), track.staves.jsElement(0).bars.jsElement(1).voices.jsElement(0).beats.jsElement(2).chord)
        try GpImporterTestHelper.checkChord(GpImporterTestHelper._createChord("Dm", 5.0, List<Double>(5.0, 6.0, 7.0, 7.0, 5.0, -1.0), List<Double>(5.0)), track.staves.jsElement(0).bars.jsElement(1).voices.jsElement(0).beats.jsElement(3).chord)
    }

    public static func checkChord(_ expected: Chord?, _ actual: Chord?) {
        TestGlobals.expect(actual == nil).toBe(expected == nil)
        if TypeHelper.isTruthy(TypeHelper.isTruthy(expected) && TypeHelper.isTruthy(actual)) {
            TestGlobals.expect(actual!.name).toBe(expected!.name)
            TestGlobals.expect(actual!.firstFret).toBe(expected!.firstFret)
            TestGlobals.expect(actual!.strings.length).toBe(expected!.strings.length)
            TestGlobals.expect(actual!.strings.join(",")).toBe(expected!.strings.join(","))
            TestGlobals.expect(actual!.barreFrets.join(",")).toBe(expected!.barreFrets.join(","))
        }
    }

    public static func checkMultiTrackLayoutConfiguration(_ track1: Score, _ track2: Score, _ trackAll: Score, _ track1And3: Score) {
        TestGlobals.expect(track1.tracks[0].isVisibleOnMultiTrack).toBe(true)
        TestGlobals.expect(track1.tracks[1].isVisibleOnMultiTrack).toBe(false)
        TestGlobals.expect(track1.tracks[2].isVisibleOnMultiTrack).toBe(false)
        TestGlobals.expect(track2.tracks[0].isVisibleOnMultiTrack).toBe(false)
        TestGlobals.expect(track2.tracks[1].isVisibleOnMultiTrack).toBe(true)
        TestGlobals.expect(track2.tracks[2].isVisibleOnMultiTrack).toBe(false)
        TestGlobals.expect(trackAll.tracks[0].isVisibleOnMultiTrack).toBe(true)
        TestGlobals.expect(trackAll.tracks[1].isVisibleOnMultiTrack).toBe(true)
        TestGlobals.expect(trackAll.tracks[2].isVisibleOnMultiTrack).toBe(true)
        TestGlobals.expect(track1And3.tracks[0].isVisibleOnMultiTrack).toBe(true)
        TestGlobals.expect(track1And3.tracks[1].isVisibleOnMultiTrack).toBe(false)
        TestGlobals.expect(track1And3.tracks[2].isVisibleOnMultiTrack).toBe(true)
    }

    public static func checkSlash(_ score: Score) {
        TestGlobals.expect(score.tracks.length).toBe(2.0)
        TestGlobals.expect(score.tracks[0].staves.length).toBe(1.0)
        TestGlobals.expect(score.tracks[0].staves[0].showSlash).toBe(true)
        TestGlobals.expect(score.tracks[0].staves[0].showTablature).toBe(true)
        TestGlobals.expect(score.tracks[0].staves[0].showStandardNotation).toBe(true)
        TestGlobals.expect(score.tracks[1].staves.length).toBe(1.0)
        TestGlobals.expect(score.tracks[1].staves[0].showSlash).toBe(false)
        TestGlobals.expect(score.tracks[1].staves[0].showTablature).toBe(true)
        TestGlobals.expect(score.tracks[1].staves[0].showStandardNotation).toBe(true)
    }

